const $ = (selector) => document.querySelector(selector);
const view = $('#view');
const state = { page: 'overview', conversations: [], selected: '', selectedConversation: '', memberConversation: '', identities: [], owner: '', tools: [], history:{conversation:'',query:'',pages:[null]} };
const pages = {
  overview: ['运行概览', '查看机器人连接、任务与运行状态。'],
  groups: ['群聊与配置', '管理每个群的触发、工具和补充交流风格。'],
  conversations: ['会话信息', '分别管理群聊、私聊及频道的基本信息和备注。'],
  members: ['会话成员', '查看已识别成员、权限与手工备注。'],
  history: ['聊天记录', '按会话搜索并分页回查原始消息。'],
  tasks: ['后台任务', '查看长任务的进度、结果与错误，支持取消和重新执行。'],
  tools: ['工具中心', '查看可用能力、运行状态和工具调用记录。'],
  memories: ['记忆管理', '用户记忆跨群共享，群记忆只属于对应群聊。'],
  legacy: ['待处理记忆', '为旧记忆确认主体，原始记录会保留。'],
  identity: ['身份与权限', '关联同一个人的不同 QQ 身份，并管理创建者权限。'],
  persona: ['主人格', '维护机器人的核心人格；保存后下一轮聊天生效。'],
  settings: ['运行配置', '动态配置模型、记忆和任务；密钥不会回显。'],
  deliveries: ['交付记录', '检查文件、图片和消息的发送结果。'],
  events: ['QQ 平台事件', '查看已订阅的 QQ 生命周期和其他事件。'],
};
function h(value) { return String(value ?? '').replace(/[&<>"']/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function short(value) { const s=String(value??''); return s.length>18 ? s.slice(0,9)+'…'+s.slice(-6) : s; }
function time(value) { if(!value) return '—'; const date=new Date(value); return Number.isNaN(date.getTime()) ? h(value) : h(date.toLocaleString('zh-CN',{hour12:false})); }
function executionStatus(status) { return {success:'成功',failed:'失败',partial:'部分完成',running:'进行中',interrupted:'已中断'}[status]||'未知'; }
function badge(status) { const text={queued:'排队中',running:'执行中',waiting:'等待答复',completed:'已完成',failed:'失败',interrupted:'已中断',cancelled:'已取消',sent:'已发送',sending:'发送中',unknown:'结果未知',retried:'已重试'}[status]??status; const style=['completed','sent'].includes(status)?'good':['failed','interrupted'].includes(status)?'fail':['waiting','running','unknown'].includes(status)?'warn':'neutral'; return `<span class="badge ${style}">${h(text)}</span>`; }
function conversationType(scope) { return {group:'QQ群',c2c:'QQ 私聊',guild:'QQ 频道',dm:'频道私信'}[scope]||'会话'; }
function platformRoleName(role) { return {owner:'群主',admin:'管理员',member:'普通成员'}[role]||'未知'; }
function conversationName(id) {
  const c=state.conversations.find((item)=>item.conversation_id===id);
  if(!c)return '未知会话';
  const name=(c.label||c.settings?.label||c.platform_name||'').trim();
  if(name)return name;
  const same=state.conversations.filter((item)=>item.scope===c.scope).sort((a,b)=>(a.first_seq??0)-(b.first_seq??0)||a.conversation_id.localeCompare(b.conversation_id));
  return `未命名${conversationType(c.scope)} ${same.findIndex((item)=>item.conversation_id===id)+1}`;
}
function messageCard(m) {
  const fromBot=m.direction==='out';
  const name=fromBot?'机器人':m.remark_name||m.sender_name||(m.user_id?identityName(m.user_id):'未命名成员');
  const role=fromBot?'机器人':m.botRole==='owner'?'机器人创建者':'机器人普通用户';
  const archived=(m.archivedAttachments||[]).map((a)=>a.status==='saved'?`<a target="_blank" rel="noopener" href="/api/attachment?conversationId=${encodeURIComponent(m.conversation_id)}&messageId=${encodeURIComponent(m.id)}&index=${Number(a.attachment_index)}">查看已保存的附件 ${Number(a.attachment_index)+1}</a>`:`<span class="muted">附件 ${Number(a.attachment_index)+1}：${a.status==='pending'?'保存中':'保存失败'}${a.error?' · '+h(a.error):''}</span>${a.status==='failed'?` <button class="btn secondary small" data-retry-attachment="${h(m.id)}" data-conversation="${h(m.conversation_id)}" data-index="${Number(a.attachment_index)}">重试保存</button>`:''}`).join(' · ');
  const attachments=m.attachments && m.attachments!=='[]'?`<details><summary>查看附件信息</summary><p>${archived||'旧记录没有本地附件，请查看原始地址是否仍然有效。'}</p><pre class="detail">${h(m.attachments)}</pre></details>`:'';
  return `<div class="message ${fromBot?'bot':''}"><div class="message-title">${h(name)} <span class="badge neutral">${h(role)}</span>${!fromBot && m.platformRole?` <span class="badge neutral">QQ ${h(platformRoleName(m.platformRole))}</span>`:''}</div><div class="muted">${time(m.timestamp)} ${m.eventType?'· '+h(m.eventType):''} ${m.is_mention?'· @机器人':''}</div><p>${h(m.content||'[附件消息]')}</p>${attachments}</div>`;
}
function historyAttachments(m) {
  let attachments=[];
  try { attachments=typeof m.attachments==='string'?JSON.parse(m.attachments):m.attachments||[]; } catch { return '<div class="chat-attachment muted">附件信息无法读取</div>'; }
  if(!Array.isArray(attachments))return '';
  return attachments.map((item,index)=>{
    const saved=(m.archivedAttachments||[]).find((entry)=>entry.attachment_index===index);
    const type=String(item?.content_type||'').toLowerCase();
    const label=item?.filename||item?.file_name||(type.startsWith('image/')?'图片':type.startsWith('audio/')?'音频':type.startsWith('video/')?'视频':'附件');
    if(saved?.status==='saved') {
      const href=`/api/attachment?conversationId=${encodeURIComponent(m.conversation_id)}&messageId=${encodeURIComponent(m.id)}&index=${index}`;
      return type.startsWith('image/')?`<a class="chat-image" href="${h(href)}" target="_blank" rel="noopener"><img loading="lazy" src="${h(href)}" alt="${h(label)}"></a>`:`<a class="chat-attachment" href="${h(href)}" target="_blank" rel="noopener"><span>▣</span><span>${h(label)}<small>点击查看或下载</small></span></a>`;
    }
    const status=saved?.status==='pending'?'正在保存':'未保存或已失效';
    return `<div class="chat-attachment unavailable"><span>▧</span><span>${h(label)}<small>${status}</small></span>${saved?.status==='failed'?`<button class="btn secondary small" data-retry-attachment="${h(m.id)}" data-conversation="${h(m.conversation_id)}" data-index="${index}">重试</button>`:''}</div>`;
  }).join('');
}
function historyMessage(m) {
  const fromBot=m.direction==='out';
  const name=fromBot?'机器人':m.remark_name||m.sender_name||(m.user_id?identityName(m.user_id):'未命名成员');
  const avatar=fromBot?'🐋':Array.from(name)[0]||'友';
  const role=!fromBot && m.botRole==='owner'?'创建者':!fromBot && m.platformRole?platformRoleName(m.platformRole):'';
  const body=m.content?`<div class="chat-text">${h(m.content)}</div>`:'';
  return `<article class="chat-message ${fromBot?'out':'in'}"><div class="chat-avatar">${h(avatar)}</div><div class="chat-message-main"><div class="chat-meta"><strong>${h(name)}</strong>${role?`<span class="chat-role">${h(role)}</span>`:''}<time>${time(m.timestamp)}</time></div><div class="chat-bubble">${body}${historyAttachments(m)||(!body?'<div class="muted">[空消息]</div>':'')}</div></div></article>`;
}
function identityNumber(userId) {
  const first=new Map();
  for(const i of state.identities)first.set(i.user_id,Math.min(first.get(i.user_id)??Infinity,i.alias_order??Infinity));
  const ids=[...first.keys()].sort((a,b)=>first.get(a)-first.get(b)||a.localeCompare(b));
  const index=ids.indexOf(userId);
  return index<0?null:index+1;
}
function identityName(userId) {
  const aliases=state.identities.filter((i)=>i.user_id===userId);
  return aliases.find((a)=>a.remark_name?.trim())?.remark_name.trim() || aliases.find((a)=>a.display_name?.trim())?.display_name.trim() || (identityNumber(userId) ? `未命名用户 ${identityNumber(userId)}` : '未识别用户');
}
function identityOptionName(userId) {
  const name=identityName(userId),ids=[...new Set(state.identities.map((i)=>i.user_id))];
  return ids.filter((id)=>identityName(id)===name).length>1 ? `${name}（用户 ${identityNumber(userId)}）` : name;
}
function toast(text, error=false) { const el=$('#toast');el.textContent=text;el.className='toast'+(error?' error':'');el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{el.hidden=true},3500); }
async function api(url, method='GET', payload) { const options={method}; if(method!=='GET'){options.headers={'Content-Type':'application/json'};options.body=JSON.stringify(payload??{});} const response=await fetch(url,options);const data=await response.json();if(!response.ok)throw Error(data.error||`HTTP ${response.status}`);return data; }
async function action(fn) { try{await fn()}catch(error){toast(error.message||'操作失败',true)} }
async function base() { const [c,i]=await Promise.all([api('/api/conversations'),api('/api/identities')]);state.conversations=c.conversations;state.identities=i.identities;state.owner=i.owner; }
async function status() { try { const s=await api('/status'); const ok=s.qqConnected;for(const id of ['#side-dot','#top-dot'])$(id).className='dot '+(ok?'ok':'bad');$('#side-status').textContent=ok?'QQ 已连接':'QQ 未连接';$('#top-status').textContent=s.phase==='ready'?'运行正常':s.phase==='waiting_qr'?'等待扫码':'检查中';return s;} catch {$('#top-status').textContent='连接失败';return null;} }
function page(name) { state.page=name;document.querySelectorAll('.nav').forEach((b)=>b.classList.toggle('active',b.dataset.page===name));$('#crumb').textContent=pages[name][0];$('#title').textContent=pages[name][0];$('#subtitle').textContent=pages[name][1];return render(); }
async function render() { view.innerHTML='<div class="empty">正在加载…</div>';try{await base();await ({overview,groups:renderGroups,conversations,members,history,tasks,tools:toolCenter,memories,legacy,identity,persona,settings,deliveries,events}[state.page])()}catch(error){view.innerHTML=`<div class="panel empty">加载失败：${h(error.message)}</div>`} }
function buttonAction(selector,fn) { view.querySelectorAll(selector).forEach((button)=>button.addEventListener('click',()=>action(()=>fn(button)))); }
function bindAttachmentRetry() {view.querySelectorAll('[data-retry-attachment]').forEach((button)=>{if(button.dataset.bound)return;button.dataset.bound='1';button.addEventListener('click',()=>action(async()=>{await api('/api/attachment/retry','POST',{conversationId:button.dataset.conversation,messageId:button.dataset.retryAttachment,index:Number(button.dataset.index)});toast('已重新开始保存附件');await render()}))})}

function toolGroups(tools, requirements, runtime, disabledTools, catalog=[]) {
  const lookup=new Map(catalog.map((entry)=>[entry.name,entry]));
  const categories=[...new Set(['联网与资料','文件与制作','消息与交付','后台任务','记忆与会话','语音',...catalog.map((entry)=>entry.category),'插件与其他'])];
  const disabled=new Set(disabledTools);
  const dependencies={web_search:'search',research_web:'search',search_images:'search',download_file:'search',read_webpage:'search',download_media:'media',extract_audio:'media',inspect_media:'media',deliver_media:'media',run_python_script:'python',run_shell_command:'python',render_image_card:'python',speak:'voice',set_voice:'voice',list_voices:'voice'};
  const permissionNames={network:'联网',process:'执行程序',workspaceRead:'读取工作区',workspaceWrite:'写入工作区'};
  const allowed=(name)=>!disabled.has(name) && (!['run_python_script','run_shell_command'].includes(name) || (!disabled.has('run_python_script')&&!disabled.has('run_shell_command')));
  return categories.map((category)=>{
    const names=tools.filter((name)=>(lookup.get(name)?.category||'插件与其他')===category);
    if(!names.length)return '';
    return `<details class="tool-section"><summary><strong>${h(category)}</strong><span>已保存允许 ${names.filter(allowed).length} / ${names.length} 项</span></summary><div class="tool-grid">${names.map((name)=>{
      const label=lookup.get(name)?.label||name,description=lookup.get(name)?.description||'暂无中文说明。';
      const coupled=['run_python_script','run_shell_command'].includes(name);
      const checked=allowed(name);
      const missing=(requirements[name]||[]).filter((key)=>runtime.permissions?.[key]===false).map((key)=>permissionNames[key]||key);
      const globalOff=dependencies[name] && runtime.tools?.[dependencies[name]]===false;
      const status=globalOff?'全局已关闭':missing.length?'沙箱缺少：'+missing.join('、'):'本群可配置';
      return `<label class="tool-card"><input type="checkbox" data-tool="${h(name)}" ${checked?'checked':''}><span><strong>${h(label)}</strong><small>${h(description)}${coupled?' Python 和命令执行会一起启用或关闭。':''}</small><span class="tool-meta">${h(status)} · ${h(name)}</span></span></label>`;
    }).join('')}</div></details>`;
  }).join('');
}

async function overview() {
  const [s,t,d,metrics]=await Promise.all([status(),api('/api/tasks'),api('/api/deliveries'),api('/api/metrics')]); const groups=state.conversations.filter((c)=>['group','guild'].includes(c.scope));const active=t.tasks.filter((x)=>['queued','running','waiting'].includes(x.status)).length;const failed=d.deliveries.filter((x)=>['failed','unknown'].includes(x.status)).length;
  view.innerHTML=`<div class="grid metrics"><div class="metric"><div class="metric-label">已记录群聊</div><div class="metric-value">${groups.length}</div><div class="metric-note">已接收到消息的群</div></div><div class="metric"><div class="metric-label">后台进行中</div><div class="metric-value">${active}</div><div class="metric-note">排队、执行或等待答复</div></div><div class="metric"><div class="metric-label">待关注交付</div><div class="metric-value">${failed}</div><div class="metric-note">失败或结果未知</div></div><div class="metric"><div class="metric-label">用户身份</div><div class="metric-value">${new Set(state.identities.map((i)=>i.user_id)).size}</div><div class="metric-note">支持跨群关联</div></div></div>
  <div class="grid overview-cols"><section class="panel"><div class="panel-head"><div><h2>启动自检</h2><div class="muted">检查当前已启用的服务与依赖</div></div><span class="badge ${s?.phase==='ready'?'good':'warn'}">${h(s?.phase??'离线')}</span></div><div class="checks">${(s?.checks||[]).map((c)=>`<div class="check"><strong><i class="dot ${c.ok?'ok':'bad'}"></i>${h(c.name)}</strong><p>${h(c.message)}</p></div>`).join('')||'<div class="empty">暂无检查结果</div>'}</div>${s?.hasQr?'<p class="muted">请使用手机 QQ 扫码绑定</p><img class="qr" src="/qr.svg" alt="QQ 扫码二维码">':''}</section>
  <div class="stack"><section class="panel"><div class="panel-head"><div><h2>最近群聊</h2><div class="muted">只有接收到的消息会出现在这里</div></div><button class="btn secondary small" id="to-groups">管理群聊</button></div><div class="list">${groups.slice(0,5).map((c)=>`<div class="list-item"><div><div class="list-title">${h(conversationName(c.conversation_id))}</div><div class="list-sub">${c.message_count} 条记录 · ${time(c.last_activity)}</div></div>${badge(c.settings?.enabled?'sent':'cancelled')}</div>`).join('')||'<div class="empty">还没有收到群聊消息</div>'}</div></section><section class="panel"><h2>近 24 小时调用</h2><p class="muted">仅统计本次更新后的调用；Token 来自服务商返回，未提供则显示未知。不包含自检的模型调用及供应商可能收取的独立搜索费用，不能作为完整账单。</p>${(metrics.totals||[]).map((m)=>`<p>${h(m.phase)}：${h(m.calls)} 次 · 失败 ${h(m.failures)} 次 · 平均 ${h(m.average_ms)} 毫秒 · Token ${m.usage_reported?h(m.total_tokens):'未知'}</p>`).join('')||'<p class="muted">暂无调用记录</p>'}<details><summary>最近调用明细</summary>${(metrics.recent||[]).slice(0,30).map((m)=>`<p class="muted">${time(m.created_at)} · ${h(conversationName(m.conversation_id))} · ${h(m.phase)} / ${h(m.name)} · ${h(executionStatus(m.status))} · ${h(m.duration_ms)} 毫秒 · Token ${m.total_tokens==null?'未知':h(m.total_tokens)}</p>`).join('')||'<p class="muted">暂无记录</p>'}</details></section><section class="panel"><h2>运行说明</h2><p class="muted">消息原文、任务和用户记忆存储在 SQLite。未触发的消息只记录，不调用模型。创建者身份和跨群身份可在身份页面维护。</p></section></div></div>`;
  $('#to-groups')?.addEventListener('click',()=>page('groups'));
}
async function renderGroups() {
  const groups=state.conversations.filter((c)=>['group','guild'].includes(c.scope)); if(!groups.some((c)=>c.conversation_id===state.selected))state.selected=groups[0]?.conversation_id||'';const selected=groups.find((c)=>c.conversation_id===state.selected);
  const [toolInfo,runtime]=await Promise.all([api('/api/tools'),api('/api/runtime-config')]);const tools=toolInfo.tools;state.tools=tools;
  const messages=selected?(await api('/api/messages?conversationId='+encodeURIComponent(state.selected))).messages:[];
  view.innerHTML=`<div class="grid two-cols"><section class="panel"><div class="panel-head"><div><h2>已发现的群</h2><div class="muted">${groups.length} 个群聊</div></div></div><div class="list">${groups.map((c)=>`<div class="list-item selectable ${c.conversation_id===state.selected?'selected':''}" data-group="${h(c.conversation_id)}"><div><div class="list-title">${h(conversationName(c.conversation_id))}</div><div class="list-sub">${c.message_count} 条 · ${time(c.last_activity)}</div></div><span class="badge ${c.settings?.enabled?'good':'neutral'}">${c.settings?.enabled?'已启用':'仅记录'}</span></div>`).join('')||'<div class="empty">等待机器人收到群消息</div>'}</div></section><div class="stack">${selected?`<section class="panel"><div class="panel-head"><div><h2>群聊设置</h2><div class="muted">变更对下一条群消息生效；主人格不会被覆盖。</div></div><button class="btn" id="save-group">保存设置</button></div><div class="form-row"><label>备注名称</label><input id="group-label" class="control" value="${h(selected.settings.label)}" placeholder="填写群名或便于识别的备注"><span class="muted">${selected.platform_name?`QQ 群名：${h(selected.platform_name)}；填写备注后优先显示备注。`:selected.platform_error?`暂未获取 QQ 群名：${h(selected.platform_error)}；可填写备注。`:'群名获取中或平台尚未提供，可填写备注。'}</span></div><label class="checkline"><input id="group-enabled" type="checkbox" ${selected.settings.enabled?'checked':''}>启用触发回复（关闭后仍记录消息）</label><div class="form-row"><label>触发关键词，每行一个（@ 始终触发）</label><textarea id="group-keywords" class="control">${h(selected.settings.keywords.join('\n'))}</textarea></div><div class="form-row"><label>回复时优先关注的时间范围（秒）</label><input id="group-window" class="control" type="number" min="10" max="900" value="${h(selected.settings.engagementWindowSeconds)}"><span class="muted">例如填写 180：被唤醒后，已加载消息中最近 3 分钟的发言会标记为近期，优先结合相关答复和纠正。它不是等待时间，不影响历史记录，也不会让普通消息单独唤醒模型。</span></div><div class="form-row"><label>本群补充交流风格</label><textarea id="group-persona" class="control" placeholder="例如：这个群更喜欢简短轻松的交流">${h(selected.settings.persona)}</textarea></div><div class="form-row"><label>本群工具开关</label><p class="muted">勾选表示允许本群使用；实际可用性还受全局设置、沙箱权限和任务阶段影响。Deep Agents 内置文件工具不在此列表中。</p>${toolGroups(tools,toolInfo.requirements,runtime,selected.settings.disabledTools,toolInfo.catalog||[])}</div></section><section class="panel"><div class="panel-head"><div><h2>最近接收与回复</h2><div class="muted">最多显示最近 100 条；事件类型有助于核对普通群消息。</div></div></div>${messages.map(messageCard).join('')||'<div class="empty">暂无记录</div>'}</section>`:'<section class="panel empty">选择一个群聊</section>'}</div></div>`;
  buttonAction('[data-group]',(b)=>{state.selected=b.dataset.group;return renderGroups()});
  bindAttachmentRetry();
  view.querySelectorAll('[data-tool]').forEach((el)=>el.addEventListener('change',()=>{if(['run_python_script','run_shell_command'].includes(el.dataset.tool))view.querySelectorAll('[data-tool]').forEach((other)=>{if(['run_python_script','run_shell_command'].includes(other.dataset.tool))other.checked=el.checked})}));
  $('#save-group')?.addEventListener('click',()=>action(async()=>{const disabledTools=[...selected.settings.disabledTools.filter((name)=>!tools.includes(name)),...[...view.querySelectorAll('[data-tool]')].filter((e)=>!e.checked).map((e)=>e.dataset.tool)];await api('/api/group','PUT',{conversationId:state.selected,settings:{label:$('#group-label').value,enabled:$('#group-enabled').checked,keywords:$('#group-keywords').value.split(/\r?\n/).map((s)=>s.trim()).filter(Boolean),persona:$('#group-persona').value,engagementWindowSeconds:Number($('#group-window').value),disabledTools}});toast('群聊设置已保存');await render()}));
}
function conversationKey(c) { return c.scope+':'+c.conversation_id; }
function conversationOptions(selected) {
  return state.conversations.map((c)=>`<option value="${h(conversationKey(c))}" ${conversationKey(c)===selected?'selected':''}>${h(conversationType(c.scope))} · ${h(conversationName(c.conversation_id))}</option>`).join('');
}
async function conversations() {
  if(!state.conversations.some((c)=>conversationKey(c)===state.selectedConversation))state.selectedConversation=state.conversations[0]?conversationKey(state.conversations[0]):'';
  const selected=state.conversations.find((c)=>conversationKey(c)===state.selectedConversation);
  view.innerHTML=`<div class="grid overview-cols"><section class="panel"><div class="panel-head"><div><h2>会话列表</h2><div class="muted">群聊和私聊分别列出；仅显示机器人接收过消息的会话。</div></div><span class="badge neutral">${state.conversations.length} 个</span></div><div class="list">${state.conversations.map((c)=>`<button class="list-item selectable ${conversationKey(c)===state.selectedConversation?'selected':''}" data-conversation="${h(conversationKey(c))}"><span><span class="list-title">${h(conversationName(c.conversation_id))}</span><span class="list-sub block">${h(conversationType(c.scope))} · ${c.message_count} 条消息</span></span></button>`).join('')||'<div class="empty">暂无会话</div>'}</div></section>${selected?`<section class="panel"><div class="panel-head"><div><h2>基本信息</h2><div class="muted">备注只保存在本地，不会修改 QQ 群或账号资料。</div></div><button id="save-conversation" class="btn">保存备注</button></div><div class="info-grid"><div><span>会话类型</span><strong>${h(conversationType(selected.scope))}</strong></div><div><span>已保存消息</span><strong>${selected.message_count} 条</strong></div><div class="wide"><span>最近活动</span><strong>${time(selected.last_activity)}</strong></div></div>${selected.scope==='group'?`<p class="muted">${selected.platform_name?`QQ 群名：${h(selected.platform_name)}${selected.platform_info?.memberCount!=null?` · ${h(selected.platform_info.memberCount)} 位成员`:''}；备注名称优先显示。`:'暂未获取到 QQ 群名，可填写备注名称。'}</p>`:'<p class="muted">名称可在此维护；QQ 未提供昵称时，请填写便于识别的备注名称。</p>'}<div class="form-row"><label>会话备注名称</label><input id="conversation-label" class="control" maxlength="100" value="${h(selected.label||'')}"></div><div class="form-row"><label>会话备注</label><textarea id="conversation-note" class="control" maxlength="2000" placeholder="记录群用途、来源等">${h(selected.note||'')}</textarea></div><div class="actions"><button id="conversation-history" class="btn secondary">查看聊天记录</button><button id="conversation-members" class="btn secondary">查看成员</button></div></section>`:'<section class="panel empty">暂无会话</section>'}</div>`;
  buttonAction('[data-conversation]',(button)=>{state.selectedConversation=button.dataset.conversation;return conversations()});
  if(!selected)return;
  $('#save-conversation').onclick=()=>action(async()=>{await api('/api/conversation-profile','PUT',{scope:selected.scope,conversationId:selected.conversation_id,label:$('#conversation-label').value,note:$('#conversation-note').value});toast('会话备注已保存');await render()});
  $('#conversation-history').onclick=()=>{state.history.conversation=selected.conversation_id;state.history.query='';state.history.pages=[null];return page('history')};
  $('#conversation-members').onclick=()=>{state.memberConversation=conversationKey(selected);return page('members')};
}
async function members() {
  if(!state.conversations.some((c)=>conversationKey(c)===state.memberConversation))state.memberConversation=state.conversations[0]?conversationKey(state.conversations[0]):'';
  const selected=state.conversations.find((c)=>conversationKey(c)===state.memberConversation);
  const result=selected?await api('/api/conversation-members?'+new URLSearchParams({conversationId:selected.conversation_id,scope:selected.scope})):{members:[]};
  view.innerHTML=`<div class="stack"><section class="panel"><div class="panel-head"><div><h2>会话成员</h2><div class="muted">群聊与私聊独立查看。成员来自已接收消息或手动添加，可能不是 QQ 完整成员名单。</div></div><span class="badge neutral">${result.members.length} 人</span></div><div class="form-row"><label>选择会话</label><select class="control" id="member-conversation">${conversationOptions(state.memberConversation)}</select></div><div class="notice">平台成员 ID 通常是 OpenID，不是 QQ 号。“创建者 / 普通用户”是本机器人权限，不代表 QQ 群主或管理员。QQ 群权限取自最近一次包含角色的消息，可能已变化；平台未提供时显示未知。修改备注不会改变权限。</div></section><section class="panel"><div class="panel-head"><h2>成员资料与备注</h2></div><div class="member-list">${result.members.map((m,index)=>`<article class="member-card"><div class="panel-head"><div><div class="list-title">${h(m.remark_name||m.display_name||identityName(m.user_id))}</div><div class="list-sub">平台名称：${h(m.display_name||'平台未提供')} · ${m.message_count?'已收到 '+m.message_count+' 条消息':'手动添加，尚未收到消息'}</div></div><span class="badge ${m.bot_role==='owner'?'good':'neutral'}">${m.bot_role==='owner'?'机器人创建者':'机器人普通用户'}</span></div><div class="list-sub">${['group','guild'].includes(selected.scope)?'QQ 群权限：'+h(platformRoleName(m.platform_role))+(m.platform_role_at?'（最近记录：'+time(m.platform_role_at)+'）':'（平台未提供）'):'私聊不适用群角色'} · 最近发言：${time(m.last_message)}</div><div class="form-row"><label>手动备注名称</label><input class="control" data-member-name="${index}" maxlength="100" value="${h(m.remark_name)}"></div><div class="form-row"><label>人工备注</label><textarea class="control" data-member-note="${index}" maxlength="2000" placeholder="记录需要人工维护的信息">${h(m.note)}</textarea></div><button class="btn secondary small" data-member-save="${index}">保存成员备注</button></article>`).join('')||'<div class="empty">尚未识别到成员</div>'}</div></section>${selected?`<details class="panel"><summary>手动添加成员</summary><p class="muted">请填写该会话中由 QQ 提供的成员 ID。手动添加不会验证此人是否在群内，也不会授予创建者权限。</p><div class="form-row"><label>平台成员 ID</label><input id="new-member-id" class="control" maxlength="300" placeholder="填写 OpenID 或频道用户 ID"></div><div class="form-row"><label>备注名称</label><input id="new-member-name" class="control" maxlength="100"></div><div class="form-row"><label>人工备注</label><textarea id="new-member-note" class="control" maxlength="2000"></textarea></div><button id="add-member" class="btn secondary">添加或更新成员</button></details>`:''}</div>`;
  $('#member-conversation').onchange=(event)=>{state.memberConversation=event.target.value;return members()};
  if(!selected)return;
  buttonAction('[data-member-save]',async(button)=>{const index=Number(button.dataset.memberSave),member=result.members[index];const name=view.querySelector(`[data-member-name="${index}"]`),note=view.querySelector(`[data-member-note="${index}"]`);await api('/api/conversation-members','PUT',{scope:selected.scope,conversationId:selected.conversation_id,externalId:member.external_id,remarkName:name.value,note:note.value});toast('成员备注已保存');await members()});
  $('#add-member').onclick=()=>action(async()=>{const externalId=$('#new-member-id').value.trim();if(!externalId)throw Error('请填写平台成员 ID');await api('/api/conversation-members','POST',{scope:selected.scope,conversationId:selected.conversation_id,externalId,remarkName:$('#new-member-name').value,note:$('#new-member-note').value});toast('成员已保存');await members()});
}
function candidateNames(value,catalog) {try{return JSON.parse(value).map((name)=>catalog.find((item)=>item.name===name)?.label||name).join('、')}catch{return '记录不可用'}}
async function tasks() { const [{tasks:items,progress,calls=[],discoveries=[],deliveries=[]},info]=await Promise.all([api('/api/tasks'),api('/api/tools')]);const catalog=info.catalog||[];view.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>任务列表</h2><div class="muted">重启后尝试从任务检查点恢复；结果未知的发送不会自动重发。</div></div><span class="badge neutral">${items.length} 个任务</span></div><div class="list">${items.map((t)=>`<article class="list-item block"><div class="panel-head"><div><div class="list-title">${h(t.instruction.slice(0,160))}${t.instruction.length>160?"…":""}</div>${t.instruction.length>160?`<details><summary>查看完整任务</summary><div class="detail">${h(t.instruction)}</div></details>`:""}<div class="list-sub">${h(conversationName(t.conversation_id))} · ${time(t.created_at)}</div></div>${badge(t.status)}</div>${t.result?`<details><summary>查看任务结果与产物</summary><div class="detail">${h(t.result)}</div></details>`:''}${t.error?`<div class="detail">错误：${h(t.error)}</div>`:''}${progress.filter((p)=>p.task_id===t.id).slice(0,4).map((p)=>`<p class="muted">${time(p.created_at)} · ${h(p.content)}</p>`).join('')}<details><summary>查看工具发现与执行记录</summary>${discoveries.filter((d)=>d.task_id===t.id).map((d)=>`<p class="muted">${time(d.created_at)} · ${d.kind==='auto'?'自动匹配':'主动查找'} ${h(d.query)} → ${h(candidateNames(d.candidates,catalog)||'没有匹配')}</p>`).join('')}${calls.filter((c)=>c.task_id===t.id).map((c)=>`<p class="muted">${time(c.created_at)} · ${h(catalog.find((entry)=>entry.name===c.name)?.label||c.name)} · ${h(executionStatus(c.status))} · ${h(c.duration_ms)} 毫秒</p>`).join('')||'<p class="muted">暂无工具执行记录</p>'}</details><details><summary>查看实际交付</summary>${deliveries.filter((d)=>d.task_id===t.id).map((d)=>`<p class="muted">${time(d.created_at)} · ${h(d.file_name||d.kind)} · ${h(({sent:'已发送',failed:'失败',unknown:'结果未知',queued:'待发送',sending:'发送中'})[d.status]||d.status)}${d.error?' · '+h(d.error):''}</p>`).join('')||'<p class="muted">暂无关联交付记录</p>'}</details><div class="actions task-actions">${['queued','running','waiting'].includes(t.status)?`<button class="btn danger small" data-task="${h(t.id)}" data-action="cancel">取消任务</button><button class="btn secondary small" data-task="${h(t.id)}" data-action="update">补充要求 / 答复</button>`:''}${['failed','interrupted','cancelled'].includes(t.status)?`<button class="btn secondary small" data-task="${h(t.id)}" data-action="retry">重新执行</button>`:''}</div></article>`).join('')||'<div class="empty">暂无后台任务</div>'}</div></section>`;
  buttonAction('[data-task]',async(b)=>{const a=b.dataset.action;let instruction;if(a==='update'){instruction=prompt('输入补充要求或答复');if(!instruction)return;}if(a==='retry'&&!confirm('重新执行可能再次下载或处理文件，确认继续？'))return;await api('/api/tasks/action','POST',{id:b.dataset.task,action:a,instruction});toast('操作已提交');await tasks()}); }
async function toolCenter() {
  const [info,activity]=await Promise.all([api('/api/tools'),api('/api/tool-activity')]);const catalog=info.catalog||[];
  const permissions={network:'联网',process:'执行程序',workspaceRead:'读取工作区',workspaceWrite:'写入工作区'};
  const label=(name)=>catalog.find((entry)=>entry.name===name)?.label||name;
  view.innerHTML=`<div class="stack"><section class="panel"><div class="panel-head"><div><h2>工具目录</h2><p class="muted">工具按需向模型展示。已启用不代表外部站点或 QQ 接口一定可用；群内开关在群聊配置中维护。</p></div><span class="badge neutral">${catalog.length} 项</span></div><input class="control" id="tool-catalog-search" placeholder="搜索中文名称、用途或分类">${info.pluginError?`<p class="notice warn-note">插件工具读取失败：${h(info.pluginError)}</p>`:''}<div class="tool-center-grid">${catalog.map((entry)=>`<article class="tool-center-card" data-catalog-search="${h(`${entry.label} ${entry.description} ${entry.category} ${entry.name}`.toLowerCase())}"><div class="panel-head"><div><div class="list-title">${h(entry.label)}</div><div class="list-sub">${h(entry.category)} · ${h(entry.source)}</div></div><span class="badge ${entry.missing?.length||entry.status==='全局已关闭'?'warn':'good'}">${entry.missing?.length||entry.status==='全局已关闭'?'未启用':'已启用'}</span></div><p>${h(entry.description)}</p><div class="tool-center-meta">${h(entry.execution)} · ${h(entry.effect)}<br>权限：${h((entry.permissions||[]).map((name)=>permissions[name]||name).join('、')||'无额外权限')}<br>${h(entry.status)}</div><details><summary>技术信息</summary><span class="muted">工具标识：${h(entry.name)}<br>输入字段：${h((entry.inputs||[]).join('、')||'无或暂未提供')}<br>输出：${h(entry.output||'以运行结果为准')}</span></details></article>`).join('')||'<div class="empty">暂无工具</div>'}</div></section><section class="panel"><h2>最近工具发现</h2><p class="muted">展示本轮自动匹配及模型主动查找工具的记录；候选不代表已经执行。</p>${(activity.discoveries||[]).map((entry)=>`<p class="tool-activity">${time(entry.created_at)} · ${h(conversationName(entry.conversation_id))}<br>${entry.kind==='auto'?'自动匹配':'主动查找'}：${h(entry.query)}<br>候选：${h(candidateNames(entry.candidates,catalog)||'没有匹配')}</p>`).join('')||'<div class="empty">暂无工具发现记录</div>'}</section><section class="panel"><h2>最近工具调用</h2><p class="muted">记录调用结果和耗时；更详细的后台步骤可在对应任务中查看。</p>${(activity.calls||[]).map((entry)=>`<p class="tool-activity">${time(entry.created_at)} · ${h(conversationName(entry.conversation_id))} · ${h(label(entry.name))} · ${h(executionStatus(entry.status))} · ${h(entry.duration_ms)} 毫秒</p>`).join('')||'<div class="empty">暂无调用记录</div>'}</section></div>`;
  $('#tool-catalog-search').oninput=(event)=>{const query=event.target.value.trim().toLowerCase();view.querySelectorAll('[data-catalog-search]').forEach((card)=>{card.hidden=!card.dataset.catalogSearch.includes(query)})};
}
async function persona() {
  const data=await api('/api/persona');
  const sources={existing:'启用记录前已有的人格',system:'系统初始化',admin:'管理页面修改',qq:'QQ 创建者明确修改'};
  view.innerHTML=`<div class="stack"><section class="panel"><div class="panel-head"><div><h2>核心人格</h2><div class="muted">跨群共享；工具结果、群聊、后台任务和群风格不能直接修改。</div></div><button class="btn" id="save-persona">保存人格</button></div><textarea id="persona-text" class="control persona-editor">${h(data.persona)}</textarea><p class="muted">保存在 SQLite；保存后下一轮聊天动态读取。QQ 中只有已确认的创建者明确要求修改时才能更改。</p></section><section class="panel"><div class="panel-head"><div><h2>人格修改记录</h2><div class="muted">只记录实际内容变化；启用记录之前无法还原修改过程。</div></div></div><div class="list">${(data.revisions||[]).map((r)=>`<div class="list-item"><div><div class="list-title">${h(sources[r.source]||r.source)}</div><div class="list-sub">${time(r.created_at)}${r.actor_id?' · '+h(identityName(r.actor_id)):''}</div></div><span class="badge neutral">版本 ${h(r.seq)}</span></div>`).join('')||'<div class="empty">暂无记录</div>'}</div></section></div>`;
  $('#save-persona').onclick=()=>action(async()=>{await api('/api/persona','PUT',{persona:$('#persona-text').value});toast('主人格已保存');await persona()});
}
async function identity() { const ids=[...new Set(state.identities.map((i)=>i.user_id))];const options=(selected='')=>ids.map((id)=>`<option value="${h(id)}" ${selected===id?'selected':''}>${h(identityOptionName(id))}</option>`).join('');view.innerHTML=`<div class="grid overview-cols"><section class="panel"><div class="panel-head"><div><h2>创建者权限</h2><div class="muted">扫描绑定返回的私聊身份用于初始化；可以在这里调整。</div></div><span class="badge good">${state.owner?'已设置':'未设置'}</span></div><div class="notice">群聊和私聊使用不同的 QQ OpenID。要让创建者在群里使用创建者权限，先将群成员身份关联到创建者身份。系统不会按昵称自动授权。</div><div class="form-row"><label>当前创建者</label><select id="owner-id" class="control">${options(state.owner)}</select></div><button id="set-owner" class="btn">设为创建者</button><div class="divider"></div><h2>关联同一个人</h2><p class="muted">合并后，两个身份的用户记忆会共享；请选择确认属于同一个人的身份。</p><div class="form-row"><label>被合并身份</label><select id="link-source" class="control">${options()}</select></div><div class="form-row"><label>保留的身份</label><select id="link-target" class="control">${options(state.owner)}</select></div><button id="link-users" class="btn secondary">关联身份</button></section><section class="panel"><div class="panel-head"><div><h2>已识别身份</h2><div class="muted">OpenID 由 QQ 平台提供，并非 QQ 号。</div></div></div><div class="list">${state.identities.map((i,index)=>`<div class="list-item"><div><div class="list-title">${h(i.remark_name||i.display_name||identityName(i.user_id))} ${i.user_id===state.owner?'<span class="badge good">创建者</span>':''}</div><div class="list-sub">${['group','guild'].includes(i.scope)?h(conversationName(i.conversation_id)):'私聊'} · ${h(identityOptionName(i.user_id))}</div></div>${state.identities.filter((a)=>a.user_id===i.user_id).length>1?`<button class="btn secondary small" data-detach="${index}">解除关联</button>`:""}</div>`).join('')||'<div class="empty">暂无用户身份</div>'}</div></section></div>`;
  $('#set-owner').onclick=()=>action(async()=>{if(!confirm('确认切换创建者身份？'))return;await api('/api/identities/owner','PUT',{userId:$('#owner-id').value});toast('创建者已更新');await render()});$('#link-users').onclick=()=>action(async()=>{if(!confirm('确认这两个身份属于同一个人？关联后会合并用户记忆。'))return;await api('/api/identities/link','POST',{source:$('#link-source').value,target:$('#link-target').value});toast('身份已关联');await render()});buttonAction('[data-detach]',async(b)=>{const i=state.identities[Number(b.dataset.detach)];if(!i||!confirm('解除后该账号会成为独立身份，原有记忆和创建者权限保留在原身份。确认解除？'))return;await api('/api/identities/detach','POST',{scope:i.scope,conversationId:i.conversation_id,externalId:i.external_id});toast('身份已解除关联');await render()}); }
async function memories() { const {memories:items}=await api('/api/memories');const ids=[...new Set(state.identities.map((i)=>i.user_id))];const groups=state.conversations.filter((c)=>['group','guild'].includes(c.scope));view.innerHTML=`<div class="grid overview-cols"><section class="panel"><div class="panel-head"><div><h2>长期记忆</h2><div class="muted">可编辑或删除；原始聊天记录不会被修改。</div></div><span class="badge neutral">${items.length} 条</span></div><div class="list">${items.map((m)=>`<div class="list-item"><div><div class="list-title">${h(m.content)}</div><div class="list-sub">${m.subject_type==='user'?'用户 · '+h(identityName(m.subject_id)):'群 · '+h(conversationName(m.subject_id))} · ${time(m.updated_at)}</div></div><div class="actions"><button class="btn secondary small" data-memory="${h(m.id)}" data-action="edit">编辑</button><button class="btn danger small" data-memory="${h(m.id)}" data-action="delete">删除</button></div></div>`).join('')||'<div class="empty">还没有长期记忆</div>'}</div></section><section class="panel"><h2>添加记忆</h2><p class="muted">用户事实可以跨群使用；群约定只在所属群里使用。</p><div class="form-row"><label>记忆类型</label><select id="memory-type" class="control"><option value="user">用户记忆</option><option value="group">群记忆</option></select></div><div class="form-row"><label>记忆主体</label><select id="memory-subject" class="control"></select></div><div class="form-row"><label>内容</label><textarea id="memory-content" class="control" maxlength="2000" placeholder="输入明确可靠、值得长期保存的事实"></textarea></div><button id="add-memory" class="btn">添加记忆</button></section></div>`;
  const fill=()=>{$('#memory-subject').innerHTML=$('#memory-type').value==='user'?ids.map((id)=>`<option value="${h(id)}">${h(identityOptionName(id))}</option>`).join(''):groups.map((g)=>`<option value="${h(g.conversation_id)}">${h(conversationName(g.conversation_id))}</option>`).join('')};$('#memory-type').onchange=fill;fill();
  $('#add-memory').onclick=()=>action(async()=>{const type=$('#memory-type').value,subjectId=$('#memory-subject').value;if(!subjectId)throw Error('请选择记忆主体');const alias=state.identities.find((i)=>i.user_id===subjectId);await api('/api/memories','POST',{type,subjectId,content:$('#memory-content').value,conversationId:type==='group'?subjectId:alias?.conversation_id});toast('记忆已添加');await memories()});
  buttonAction('[data-memory]',async(b)=>{const item=items.find((m)=>m.id===b.dataset.memory);if(b.dataset.action==='delete'){if(!confirm('确认删除这条记忆？原始聊天不会删除。'))return;await api('/api/memories','DELETE',{id:item.id})}else{const content=prompt('编辑记忆',item.content);if(content===null)return;await api('/api/memories','PUT',{id:item.id,content})}toast('记忆已更新');await memories()}); }
async function settings() {
  const [c,pluginInfo]=await Promise.all([api('/api/runtime-config'),api('/api/plugins')]);
  view.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>模型与运行参数</h2><div class="muted">保存在 SQLite，优先于 .env；新回合生效。密钥留空保持原值。</div></div><button id="save-settings" class="btn">保存配置</button></div><div class="form-row"><label>接口类型</label><select class="control" id="model-provider"><option value="openai" ${c.model.provider==='openai'?'selected':''}>OpenAI 兼容</option><option value="anthropic" ${c.model.provider==='anthropic'?'selected':''}>Anthropic 兼容</option></select></div><div class="form-row"><label>接口地址</label><input class="control" id="model-base" value="${h(c.model.baseUrl)}"></div><div class="form-row"><label>模型名称</label><input class="control" id="model-name" value="${h(c.model.name)}"></div><div class="form-row"><label>API 密钥（${c.apiKeyConfigured?'已配置':'未配置'}）</label><input class="control" id="model-key" type="password" autocomplete="new-password" placeholder="留空保持原密钥"></div><label class="checkline"><input type="checkbox" id="model-vision" ${c.model.vision?'checked':''}>启用图片理解</label><label class="checkline"><input type="checkbox" id="model-review" ${c.model.semanticReview?'checked':''}>启用多人聊天语义复核</label><p class="muted">关闭可减少模型调用和延迟，但可能更容易遗漏相关发言。</p><div class="settings-grid"><div class="setting-card"><h3>模型上下文窗口</h3><div class="form-row"><label for="model-context">上下文容量（Token）</label><input class="control" id="model-context" type="number" min="4096" max="1048576" value="${c.model.contextTokens}"></div><p>用于模型上下文管理，不会让每次请求自动发送这么多内容。应按模型服务商公布的窗口填写；输入和输出共同占用窗口。</p></div><div class="setting-card"><h3>近期对话</h3><div class="form-row"><label for="memory-recent">最多读取近期消息（条）</label><input class="control" id="memory-recent" type="number" min="5" max="300" value="${c.memory.recentMessages}"></div><p>被唤醒时从记录中读取，实际给模型的背景仍有长度限制；普通消息只记录，不因此调用模型。</p></div><div class="setting-card"><h3>长期记忆整理</h3><div class="form-row"><label for="memory-budget">待整理内容预算（字符）</label><input class="control" id="memory-budget" type="number" min="1000" max="200000" value="${c.memory.summaryBudgetChars}"></div><div class="form-row"><label for="memory-percent">达到预算的百分之多少时整理（%）</label><input class="control" id="memory-percent" type="number" min="1" max="100" value="${c.memory.summaryThresholdPercent}"></div><p>按未整理消息正文及说话人信息的字符量估算，包含每条消息的固定开销；不是 Token 用量，也不是模型窗口百分比。达到阈值后在回复完成时异步整理，原始消息始终保留。</p></div><div class="setting-card"><h3>后台任务</h3><div class="form-row"><label for="task-concurrency">最多同时运行的任务数</label><input class="control" id="task-concurrency" type="number" min="1" max="8" value="${c.tasks.concurrency}"></div><p>较高并发可以减少排队，但多个下载、转换或模型调用会同时占用网络、计算资源和额度。</p></div></div><label class="checkline"><input type="checkbox" id="tool-search" ${c.tools.search?'checked':''}>启用搜索</label><label class="checkline"><input type="checkbox" id="tool-media" ${c.tools.media?'checked':''}>启用媒体处理</label><label class="checkline"><input type="checkbox" id="tool-python" ${c.tools.python?'checked':''}>启用脚本执行</label></section>`;
  view.insertAdjacentHTML('beforeend',`<section class="panel"><div class="panel-head"><div><h2>配置来源</h2><div class="muted">清除页面保存的覆盖项，恢复使用 .env 和配置文件；不会修改这些文件。</div></div><button id="reset-settings" class="btn secondary">恢复文件配置</button></div></section><section class="panel"><div class="panel-head"><div><h2>工具插件</h2><div class="muted">将插件放到映射目录后重载；全部通过自检才切换，新回合生效。</div></div><button id="reload-plugins" class="btn secondary">自检并重载</button></div><div class="list">${pluginInfo.plugins.map((p)=>`<div class="list-item"><div class="list-title">${h(p.name)}</div><div class="list-sub">权限：${h(p.permissions.join('、')||'无')}</div></div>`).join('')||'<div class="empty">尚未安装插件</div>'}</div></section>`);
  $('#reset-settings').onclick=()=>action(async()=>{if(!confirm('确认清除页面保存的模型和运行覆盖配置，恢复读取 .env 与配置文件？'))return;await api('/api/runtime-config','DELETE');toast('已恢复文件配置');await settings()});
  $('#reload-plugins').onclick=()=>action(async()=>{await api('/api/plugins/reload','POST');toast('插件自检通过，已重载');await settings()});
  $('#save-settings').onclick=()=>action(async()=>{const model={provider:$('#model-provider').value,baseUrl:$('#model-base').value,name:$('#model-name').value,vision:$('#model-vision').checked,semanticReview:$('#model-review').checked,contextTokens:Number($('#model-context').value)};if($('#model-key').value)model.apiKey=$('#model-key').value;await api('/api/runtime-config','PUT',{model,memory:{recentMessages:Number($('#memory-recent').value),summaryBudgetChars:Number($('#memory-budget').value),summaryThresholdPercent:Number($('#memory-percent').value)},tasks:{concurrency:Number($('#task-concurrency').value)},tools:{search:$('#tool-search').checked,media:$('#tool-media').checked,python:$('#tool-python').checked}});toast('配置已保存，新回合生效');await settings()});
}
async function history() {
  const x=state.history;if(!state.conversations.some((c)=>c.conversation_id===x.conversation))x.conversation=state.conversations[0]?.conversation_id||'';
  const version=x.version=(x.version||0)+1;
  const params=new URLSearchParams({conversationId:x.conversation,q:x.query});
  const data=x.conversation?await api('/api/messages?'+params):{messages:[],hasMore:false,nextBefore:null};
  if(x.version!==version||state.page!=='history')return;
  const selected=state.conversations.find((c)=>c.conversation_id===x.conversation);
  view.innerHTML=`<section class="history-shell"><div class="history-toolbar"><div><h2>聊天记录</h2><p>按会话回看原始消息、图片和文件</p></div><div class="history-filters"><label><span>选择会话</span><select id="history-conversation" class="control">${state.conversations.map((c)=>`<option value="${h(c.conversation_id)}" ${x.conversation===c.conversation_id?'selected':''}>${h(conversationName(c.conversation_id))}</option>`).join('')}</select></label><label class="history-search"><span>搜索记录</span><div><input id="history-query" class="control" value="${h(x.query)}" placeholder="搜索消息或发言人"><button id="history-search" class="btn">搜索</button></div></label></div></div><div class="history-chat-head"><div class="history-chat-icon">${selected?.scope==='group'?'群':'聊'}</div><div><strong>${h(selected?conversationName(selected.conversation_id):'暂无会话')}</strong><span>${h(selected?conversationType(selected.scope):'选择会话后查看')}${x.query?' · 搜索结果':''}</span></div></div><div class="history-scroll" id="history-scroll" tabindex="0" aria-label="聊天记录，向上滚动查看更早的消息"><div class="history-more"><button id="history-older" class="btn secondary small" ${data.hasMore?'':'hidden'}>加载更早消息</button><span id="history-start" class="muted" ${data.hasMore?'hidden':''}>${data.messages.length?'已到最早记录':''}</span></div><div id="history-messages" class="history-messages">${data.messages.map(historyMessage).join('')||'<div class="empty">没有匹配的聊天记录</div>'}</div></div><div class="history-foot"><span>原始消息只读 · 图片和文件按需查看</span><button id="history-bottom" class="btn quiet small">回到最新</button></div></section>`;
  const viewport=$('#history-scroll'),list=$('#history-messages'),older=$('#history-older'),start=$('#history-start');
  let nextBefore=data.nextBefore,hasMore=data.hasMore,loading=false;
  const loadOlder=async()=>{
    if(loading||!hasMore||!nextBefore)return;
    loading=true;older.disabled=true;older.textContent='加载中…';
    try {
      const more=new URLSearchParams({conversationId:x.conversation,q:x.query,before:String(nextBefore)});
      const result=await api('/api/messages?'+more);
      if(x.version!==version||state.page!=='history')return;
      const previousHeight=viewport.scrollHeight;
      list.insertAdjacentHTML('afterbegin',result.messages.map(historyMessage).join(''));
      viewport.scrollTop+=viewport.scrollHeight-previousHeight;
      nextBefore=result.nextBefore;hasMore=result.hasMore;older.hidden=!hasMore;start.hidden=hasMore;
      bindAttachmentRetry();
    } catch(error) {toast(error.message||'加载历史消息失败',true);}
    finally {loading=false;if(x.version===version){older.disabled=false;older.textContent='加载更早消息';}}
  };
  $('#history-conversation').onchange=(e)=>{x.conversation=e.target.value;return history()};
  $('#history-search').onclick=()=>{x.query=$('#history-query').value;return history()};
  $('#history-query').onkeydown=(e)=>{if(e.key==='Enter')$('#history-search').onclick()};
  older.onclick=loadOlder;viewport.onscroll=()=>{if(viewport.scrollTop<64&&viewport.scrollHeight>viewport.clientHeight)void loadOlder()};
  $('#history-bottom').onclick=()=>history();
  viewport.scrollTop=viewport.scrollHeight;
  bindAttachmentRetry();
}
async function legacy() {
  const {memories:items}=await api('/api/memories/legacy');const ids=[...new Set(state.identities.map((i)=>i.user_id))];const groups=state.conversations.filter((c)=>['group','guild'].includes(c.scope));
  view.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>待确认主体的旧记忆</h2><div class="muted">选择用户或群并确认内容后加入长期记忆；原记录保留。</div></div><span class="badge neutral">${items.length} 条</span></div><div class="list">${items.map((m)=>`<article class="list-item block"><p>${h(m.content)}</p><div class="list-sub">来源：${h(conversationName(m.conversation_id))} · ${time(m.created_at)} · 原主体待确认</div><div class="form-row"><select class="control" data-legacy-type="${h(m.id)}"><option value="user">用户记忆</option><option value="group">群记忆</option></select><select class="control" data-legacy-subject="${h(m.id)}"></select><textarea class="control" data-legacy-content="${h(m.id)}">${h(m.content)}</textarea><button class="btn secondary small" data-resolve="${h(m.id)}">确认归属</button></div></article>`).join('')||'<div class="empty">没有待处理的旧记忆</div>'}</div></section>`;
  view.querySelectorAll('[data-legacy-type]').forEach((el)=>{const subject=[...view.querySelectorAll('[data-legacy-subject]')].find((s)=>s.dataset.legacySubject===el.dataset.legacyType);const fill=()=>{subject.innerHTML=el.value==='user'?ids.map((id)=>`<option value="${h(id)}">${h(identityOptionName(id))}</option>`).join(''):groups.map((g)=>`<option value="${h(g.conversation_id)}">${h(conversationName(g.conversation_id))}</option>`).join('')};el.onchange=fill;fill()});
  buttonAction('[data-resolve]',async(b)=>{const find=(key)=>[...view.querySelectorAll(`[data-legacy-${key}]`)].find((e)=>e.dataset['legacy'+key[0].toUpperCase()+key.slice(1)]===b.dataset.resolve);const type=find('type').value,subjectId=find('subject').value,content=find('content').value;if(!subjectId)throw Error('请选择记忆主体');await api('/api/memories/legacy','POST',{id:b.dataset.resolve,type,subjectId,content});toast('记忆已归属');await legacy()});
}
async function events() { const {events:items}=await api('/api/qq-events');view.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>平台事件</h2><div class="muted">仅展示机器人已订阅且平台实际推送的事件，最近 100 条。</div></div><span class="badge neutral">${items.length} 条</span></div><div class="list">${items.map((e)=>`<div class="list-item block"><div class="list-title">${h(e.event_type)}</div><div class="list-sub">${time(e.received_at)}</div><details><summary>查看原始事件</summary><pre class="detail">${h(e.payload)}</pre></details></div>`).join('')||'<div class="empty">暂无事件</div>'}</div></section>`; }
async function deliveries() { const {deliveries:items}=await api('/api/deliveries');view.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>发送与交付</h2><div class="muted">结果未知时不会自动重发，避免重复消息。</div></div><span class="badge neutral">最近 ${items.length} 条</span></div><div class="list">${items.map((d)=>`<div class="list-item"><div><div class="list-title">${h(d.file_name||d.kind)} · ${h(conversationName(d.conversation_id))}</div><div class="list-sub">${time(d.created_at)} ${d.error?'· '+h(d.error):''}</div></div><div class="actions">${badge(d.status)}${['failed','queued'].includes(d.status)?`<button class="btn secondary small" data-delivery="${h(d.id)}" data-conversation="${h(d.conversation_id)}">重试</button>`:''}</div></div>`).join('')||'<div class="empty">暂无交付记录</div>'}</div></section>`;buttonAction('[data-delivery]',async(b)=>{if(!confirm('确认尝试向原会话重新发送？'))return;await api('/api/deliveries/retry','POST',{id:b.dataset.delivery,conversationId:b.dataset.conversation});toast('发送成功');await deliveries()}); }
document.querySelectorAll('.nav').forEach((b)=>b.onclick=()=>page(b.dataset.page));$('#refresh').onclick=()=>render();status();setInterval(status,10000);render();
